BEGIN; CREATE TEMP TABLE measured ("deployment_id" character varying(128) NOT NULL,"recovery_public_key" bytea NOT NULL,"dropped_slot_3" integer);ALTER TABLE measured DROP COLUMN "dropped_slot_3";CREATE UNIQUE INDEX measured_index_0 ON measured USING btree (deployment_id, recovery_public_key);INSERT INTO measured(deployment_id,recovery_public_key) SELECT 'fixture-deployment',decode(md5(i::text)||md5('key-'||i::text),'hex') FROM generate_series(1,10000) n(i); SELECT json_build_object('rows',count(*),'avg_tuple_bytes',avg(pg_column_size(d)),'heap_bytes',pg_table_size('measured'),'index_bytes',pg_indexes_size('measured'),'total_bytes',pg_total_relation_size('measured'),'dropped_slots',(SELECT count(*) FROM pg_attribute WHERE attrelid='measured'::regclass AND attnum>0 AND attisdropped)) FROM measured d; ROLLBACK;